insert into public.exercises (name, zone, muscles, equipment, level, steps, mistakes) values
  ('Hip thrust con barra', 'Glúteos', 'Glúteo mayor, femorales', 'Barra, banco', 'Intermedio', '["Apoyá la parte baja de los omóplatos en el borde del banco.", "Pies al ancho de cadera, rodillas a 90° en la posición alta.", "Barra sobre la cadera, con almohadilla.", "Empujá con los talones hasta alinear rodillas, cadera y hombros.", "Apretá glúteos 2 segundos arriba y bajá controlando."]'::jsonb, '["Arquear la zona lumbar al subir.", "Empujar con la punta de los pies.", "Mirar al techo: la vista va hacia adelante, mentón adentro."]'::jsonb),
  ('Peso muerto rumano', 'Femorales', 'Femorales, glúteos, erectores', 'Barra o mancuernas', 'Intermedio', '["Parada, pies al ancho de cadera, barra pegada a los muslos.", "Rodillas apenas flexionadas y fijas.", "Llevá la cadera hacia atrás bajando la barra pegada a las piernas.", "Bajá hasta sentir el estiramiento en femorales (media tibia).", "Volvé empujando la cadera hacia adelante."]'::jsonb, '["Redondear la espalda.", "Flexionar las rodillas como en una sentadilla.", "Alejar la barra del cuerpo."]'::jsonb),
  ('Sentadilla búlgara', 'Glúteos', 'Glúteos, cuádriceps', 'Banco, mancuernas', 'Intermedio', '["Empeine del pie de atrás apoyado en el banco.", "Pie de adelante a un paso largo del banco.", "Bajá en vertical hasta que el muslo de adelante quede paralelo al piso.", "Subí empujando con el talón de adelante."]'::jsonb, '["Pie delantero demasiado cerca del banco.", "Rodilla que se va hacia adentro.", "Torso que cae hacia adelante sin control."]'::jsonb),
  ('Abducción en máquina', 'Aductores y abductores', 'Glúteo medio y menor', 'Máquina de abductores', 'Principiante', '["Sentate con la espalda apoyada y las piernas juntas.", "Abrí las piernas de forma controlada.", "Sostené 1 segundo afuera y volvé lento."]'::jsonb, '["Usar envión.", "Despegar la espalda del respaldo."]'::jsonb),
  ('Sentadilla libre', 'Cuádriceps', 'Cuádriceps, glúteos, core', 'Barra, rack', 'Intermedio', '["Barra apoyada sobre los trapecios, manos un poco más anchas que los hombros.", "Pies al ancho de hombros, puntas levemente hacia afuera.", "Inhalá, apretá el abdomen y bajá llevando la cadera atrás y abajo.", "Rodillas en la dirección de las puntas de los pies.", "Bajá hasta muslos paralelos o un poco más y subí empujando el piso."]'::jsonb, '["Levantar los talones.", "Rodillas hacia adentro al subir.", "Redondear la espalda abajo."]'::jsonb),
  ('Prensa 45°', 'Cuádriceps', 'Cuádriceps, glúteos', 'Máquina de prensa', 'Principiante', '["Espalda y cadera bien apoyadas en el respaldo.", "Pies al ancho de cadera en el centro de la plataforma.", "Bajá hasta formar 90° en las rodillas.", "Empujá sin bloquear las rodillas arriba."]'::jsonb, '["Despegar la cadera del asiento al bajar.", "Bloquear las rodillas."]'::jsonb),
  ('Sillón de cuádriceps', 'Cuádriceps', 'Cuádriceps', 'Máquina de extensiones', 'Principiante', '["Rodilla alineada con el eje de la máquina.", "Extendé las piernas por completo.", "Pausa arriba y bajá en 2-3 segundos."]'::jsonb, '["Balancear el cuerpo.", "Bajar de golpe."]'::jsonb),
  ('Estocadas caminando', 'Glúteos', 'Glúteos, cuádriceps', 'Mancuernas', 'Principiante', '["Parada con una mancuerna en cada mano.", "Da un paso largo hacia adelante.", "Bajá hasta que la rodilla de atrás casi toque el piso.", "Empujá con el talón de adelante y avanzá con la otra pierna."]'::jsonb, '["Pasos cortos que cargan la rodilla.", "Torso inclinado hacia adelante."]'::jsonb),
  ('Jalón al pecho', 'Espalda', 'Dorsales, bíceps', 'Polea alta', 'Principiante', '["Agarre un poco más ancho que los hombros.", "Pecho arriba y leve inclinación hacia atrás.", "Llevá la barra hasta el pecho bajando los codos.", "Volvé estirando los brazos de forma controlada."]'::jsonb, '["Tirar con los brazos sin bajar los hombros.", "Llevar la barra detrás de la nuca."]'::jsonb),
  ('Remo con mancuerna', 'Espalda', 'Dorsales, romboides, bíceps', 'Mancuerna', 'Principiante', '["Inclinate desde la cadera con la espalda recta.", "Brazo estirado con la mancuerna colgando.", "Llevá el codo hacia atrás, pegado al cuerpo.", "Bajá lento hasta estirar el brazo."]'::jsonb, '["Girar el torso para subir más peso.", "Encoger el hombro hacia la oreja."]'::jsonb),
  ('Press militar con mancuernas', 'Hombros', 'Deltoides, tríceps', 'Mancuernas', 'Intermedio', '["Mancuernas a la altura de los hombros, palmas hacia adelante.", "Abdomen y glúteos firmes.", "Empujá hacia arriba hasta estirar los brazos.", "Bajá controlando hasta la altura de las orejas."]'::jsonb, '["Arquear la espalda.", "Bajar demasiado rápido."]'::jsonb),
  ('Plancha frontal', 'Core', 'Recto abdominal, transverso', 'Colchoneta', 'Principiante', '["Antebrazos en el piso, codos debajo de los hombros.", "Cuerpo en línea recta de cabeza a talones.", "Apretá abdomen y glúteos.", "Respirá normal y sostené el tiempo indicado."]'::jsonb, '["Cadera caída.", "Cola muy alta.", "Contener la respiración."]'::jsonb)
